com.mirth.connect.plugins.javascriptstep.script:
/*
 * ORU_R01_IN
 * Source Transformer
 *
 * Extract important transaction, patient, order,
 * and observation values from the inbound ORU^R01.
 *
 * These values become the operational context used
 * by validation, audit persistence, ACK policy,
 * quarantine handling, and later FHIR reconciliation.
 */


/* ---------------------------------------------------------
 * MESSAGE / TRANSACTION
 * --------------------------------------------------------- */

var messageControlId =
    String(msg['MSH']['MSH.10']['MSH.10.1']);

var messageType =
    String(msg['MSH']['MSH.9']['MSH.9.1']);

var triggerEvent =
    String(msg['MSH']['MSH.9']['MSH.9.2']);

var messageStructure =
    String(msg['MSH']['MSH.9']['MSH.9.3']);

var sendingApplication =
    String(msg['MSH']['MSH.3']['MSH.3.1']);

var sendingFacility =
    String(msg['MSH']['MSH.4']['MSH.4.1']);

/*
 * Hash the exact inbound payload once so accepted, replayed,
 * conflicting, and invalid receipts use the same evidence.
 */
var rawPayload =
    String(connectorMessage.getRawData());

var digest =
    java.security.MessageDigest
        .getInstance("SHA-256");

var hashBytes =
    digest.digest(
        new java.lang.String(rawPayload)
            .getBytes("UTF-8")
    );

var payloadSha256 =
    java.lang.StringBuilder();

for (var hashIndex = 0; hashIndex < hashBytes.length; hashIndex++) {
    payloadSha256.append(
        java.lang.Integer
            .toHexString(
                (hashBytes[hashIndex] & 0xff) | 0x100
            )
            .substring(1)
    );
}


/* ---------------------------------------------------------
 * PATIENT IDENTITY
 * --------------------------------------------------------- */

var patientIdentifier =
    String(msg['PID']['PID.3']['PID.3.1']);

var assigningAuthority =
    String(msg['PID']['PID.3']['PID.3.4']);

var identifierType =
    String(msg['PID']['PID.3']['PID.3.5']);


/* ---------------------------------------------------------
 * ORDER / REPORT
 * --------------------------------------------------------- */

var placerOrderNumber =
    String(msg['OBR']['OBR.2']['OBR.2.1']);

var obrSetId =
    String(msg['OBR']['OBR.1']['OBR.1.1']);

var fillerOrderNumber =
    String(msg['OBR']['OBR.3']['OBR.3.1']);

var serviceCode =
    String(msg['OBR']['OBR.4']['OBR.4.1']);

var serviceText =
    String(msg['OBR']['OBR.4']['OBR.4.2']);

var serviceCodingSystem =
    String(msg['OBR']['OBR.4']['OBR.4.3']);

var observationDatetime =
    String(msg['OBR']['OBR.7']['OBR.7.1']);

var obrResultStatus =
    String(msg['OBR']['OBR.25']['OBR.25.1']);


/* ---------------------------------------------------------
 * ORDERED OBSERVATION COLLECTION
 * --------------------------------------------------------- */

var observations = [];
var observationSequence = 0;

for each (var obxSegment in msg['OBX']) {
    observationSequence++;

    observations.push({
        sequence: observationSequence,
        obx_set_id: String(
            obxSegment['OBX.1']['OBX.1.1']
        ),
        value_type: String(
            obxSegment['OBX.2']['OBX.2.1']
        ),
        code: String(
            obxSegment['OBX.3']['OBX.3.1']
        ),
        text: String(
            obxSegment['OBX.3']['OBX.3.2']
        ),
        coding_system: String(
            obxSegment['OBX.3']['OBX.3.3']
        ),
        value: String(
            obxSegment['OBX.5']['OBX.5.1']
        ),
        units: String(
            obxSegment['OBX.6']['OBX.6.1']
        ),
        reference_range: String(
            obxSegment['OBX.7']['OBX.7.1']
        ),
        abnormal_flag: String(
            obxSegment['OBX.8']['OBX.8.1']
        ),
        result_status: String(
            obxSegment['OBX.11']['OBX.11.1']
        )
    });
}

var firstObservation =
    observations.length > 0
        ? observations[0]
        : {
            value_type: "",
            code: "",
            text: "",
            coding_system: "",
            value: "",
            units: "",
            reference_range: "",
            abnormal_flag: "",
            result_status: ""
        };


/* ---------------------------------------------------------
 * PUBLISH OPERATIONAL CONTEXT
 * --------------------------------------------------------- */

channelMap.put(
    "oru_message_control_id",
    messageControlId
);

channelMap.put(
    "oru_message_type",
    messageType
);

channelMap.put(
    "oru_trigger_event",
    triggerEvent
);

channelMap.put(
    "oru_message_structure",
    messageStructure
);

channelMap.put(
    "oru_sending_application",
    sendingApplication
);

channelMap.put(
    "oru_sending_facility",
    sendingFacility
);

channelMap.put(
    "oru_payload_sha256",
    String(payloadSha256)
);

channelMap.put(
    "oru_patient_identifier",
    patientIdentifier
);

channelMap.put(
    "oru_assigning_authority",
    assigningAuthority
);

channelMap.put(
    "oru_identifier_type",
    identifierType
);

channelMap.put(
    "oru_placer_order_number",
    placerOrderNumber
);

channelMap.put(
    "oru_obr_set_id",
    obrSetId
);

channelMap.put(
    "oru_filler_order_number",
    fillerOrderNumber
);

channelMap.put(
    "oru_service_code",
    serviceCode
);

channelMap.put(
    "oru_service_text",
    serviceText
);

channelMap.put(
    "oru_service_coding_system",
    serviceCodingSystem
);

channelMap.put(
    "oru_observation_datetime",
    observationDatetime
);

channelMap.put(
    "oru_obr_status",
    obrResultStatus
);

channelMap.put(
    "oru_obx_value_type",
    firstObservation.value_type
);

channelMap.put(
    "oru_observation_code",
    firstObservation.code
);

channelMap.put(
    "oru_observation_text",
    firstObservation.text
);

channelMap.put(
    "oru_observation_coding_system",
    firstObservation.coding_system
);

channelMap.put(
    "oru_observation_value",
    firstObservation.value
);

channelMap.put(
    "oru_units",
    firstObservation.units
);

channelMap.put(
    "oru_reference_range",
    firstObservation.reference_range
);

channelMap.put(
    "oru_abnormal_flag",
    firstObservation.abnormal_flag
);

channelMap.put(
    "oru_obx_status",
    firstObservation.result_status
);

channelMap.put(
    "oru_observations_json",
    JSON.stringify(observations)
);

channelMap.put(
    "oru_observation_count",
    String(observations.length)
);


/* ---------------------------------------------------------
 * AUTHORITATIVE TRANSPORT RECEIPT CLASSIFICATION
 * --------------------------------------------------------- */

var auditDbConn = null;

try {
    var auditDbUrl =
        java.lang.System.getenv("INTEROP_DB_URL");

    var auditDbUser =
        java.lang.System.getenv("INTEROP_DB_USER");

    var auditDbPassword =
        java.lang.System.getenv("INTEROP_DB_PASSWORD");

    if (
        auditDbUrl == null ||
        auditDbUser == null ||
        auditDbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }

    auditDbConn =
        DatabaseConnectionFactory.createDatabaseConnection(
            "org.postgresql.Driver",
            auditDbUrl,
            auditDbUser,
            auditDbPassword
        );

    var receiptSql =
        "SELECT recorded_audit_id, " +
        "logical_transaction_id, classified_outcome " +
        "FROM audit.record_interface_receipt(" +
        "CAST(? AS VARCHAR), CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR))";

    var receiptParameters =
        new java.util.ArrayList();

    receiptParameters.add(messageControlId);
    receiptParameters.add(messageType);
    receiptParameters.add(triggerEvent);
    receiptParameters.add(patientIdentifier);
    receiptParameters.add(sendingApplication);
    receiptParameters.add(sendingFacility);
    receiptParameters.add(String(payloadSha256));

    var receiptResult =
        auditDbConn.executeCachedQuery(
            receiptSql,
            receiptParameters
        );

    if (!receiptResult.next()) {
        throw new Error(
            "record_interface_receipt returned no classification result."
        );
    }

    var recordedAuditId =
        receiptResult.getString(
            "recorded_audit_id"
        );

    var logicalTransactionId =
        receiptResult.getString(
            "logical_transaction_id"
        );

    var classifiedOutcome =
        receiptResult.getString(
            "classified_outcome"
        );

    if (classifiedOutcome == null) {
        throw new Error(
            "record_interface_receipt returned a null classification."
        );
    }

    channelMap.put(
        "audit_recorded_audit_id",
        String(recordedAuditId)
    );

    channelMap.put(
        "audit_logical_transaction_id",
        String(logicalTransactionId)
    );

    channelMap.put(
        "audit_attempt_outcome",
        String(classifiedOutcome)
    );

    logger.info(
        "ORU receipt classification: outcome=" +
        classifiedOutcome +
        ", transaction_id=" +
        logicalTransactionId +
        ", audit_id=" +
        recordedAuditId
    );
}
finally {
    if (auditDbConn != null) {
        auditDbConn.close();
    }
}


/* ---------------------------------------------------------
 * OPERATOR TRACE
 * --------------------------------------------------------- */

logger.info(
    "ORU result context: " +
    "control_id=" + messageControlId +
    ", patient_id=" + patientIdentifier +
    ", placer_order=" + placerOrderNumber +
    ", filler_order=" + fillerOrderNumber +
    ", observation_count=" + observations.length +
    ", first_observation=" + firstObservation.code +
    ", obr_status=" + obrResultStatus +
    ", obx_status=" + firstObservation.result_status
);

/*
 * ORU_R01_IN semantic validation.
 *
 * Validate one OBR containing one or more ordered OBX segments.
 * The SYN-CHEM-4 local panel profile has explicit member policy;
 * legacy single-analyte LOINC messages retain code equality.
 */

var failures = [];

function valueOf(name) {
    var value = channelMap.get(name);

    if (value == null) {
        return "";
    }

    return String(value).trim();
}

var messageControlId =
    valueOf("oru_message_control_id");

var messageType =
    valueOf("oru_message_type");

var triggerEvent =
    valueOf("oru_trigger_event");

var messageStructure =
    valueOf("oru_message_structure");

var patientIdentifier =
    valueOf("oru_patient_identifier");

var assigningAuthority =
    valueOf("oru_assigning_authority");

var identifierType =
    valueOf("oru_identifier_type");

var placerOrderNumber =
    valueOf("oru_placer_order_number");

var fillerOrderNumber =
    valueOf("oru_filler_order_number");

var serviceCode =
    valueOf("oru_service_code");

var serviceCodingSystem =
    valueOf("oru_service_coding_system");

var observationDatetime =
    valueOf("oru_observation_datetime");

var obrStatus =
    valueOf("oru_obr_status");

var observations = JSON.parse(
    valueOf("oru_observations_json") || "[]"
);

var syntheticPanelMembers = {
    "2345-7": true,
    "3094-0": true,
    "2160-0": true,
    "2951-2": true
};

var isSyntheticPanel =
    serviceCode == "SYN-CHEM-4" &&
    serviceCodingSystem == "L";


if (!messageControlId) {
    failures.push("Message control ID present");
}

if (messageType != "ORU") {
    failures.push("Message type is ORU");
}

if (triggerEvent != "R01") {
    failures.push("Trigger event is R01");
}

if (messageStructure != "ORU_R01") {
    failures.push("Message structure is ORU_R01");
}

if (!patientIdentifier) {
    failures.push("Patient ID present");
}

if (!assigningAuthority) {
    failures.push("Assigning authority present");
}

if (identifierType != "MR") {
    failures.push("Identifier type is MR");
}

if (!placerOrderNumber) {
    failures.push("Placer order number present");
}

if (!fillerOrderNumber) {
    failures.push("Filler order number present");
}

if (!serviceCode) {
    failures.push("OBR service code present");
}

if (
    serviceCodingSystem != "LN" &&
    !isSyntheticPanel
) {
    failures.push("OBR coding system is LOINC");
}

if (!/^\d{14}([+-]\d{4})?$/.test(observationDatetime)) {
    failures.push(
        "OBR-7 must be YYYYMMDDHHMMSS with an optional +/-ZZZZ offset"
    );
}

if (
    obrStatus != "F" &&
    obrStatus != "P" &&
    obrStatus != "C" &&
    obrStatus != "I" &&
    obrStatus != "X"
) {
    failures.push("OBR result status recognized");
}

if (observations.length == 0) {
    failures.push("At least one OBX observation present");
}

var observedPanelMembers = {};

for (var observationIndex = 0;
     observationIndex < observations.length;
     observationIndex++) {
    var observation = observations[observationIndex];
    var location = "OBX[" + (observationIndex + 1) + "] ";

    if (
        observation.value_type != "NM" &&
        observation.value_type != "ST" &&
        observation.value_type != "TX" &&
        observation.value_type != "CE" &&
        observation.value_type != "CWE"
    ) {
        failures.push(location + "OBX value type recognized");
    }

    if (!observation.code) {
        failures.push(location + "OBX observation code present");
    }

    if (observation.coding_system != "LN") {
        failures.push(location + "OBX coding system is LOINC");
    }

    if (!observation.value) {
        failures.push(location + "OBX observation value present");
    }

    if (
        observation.value_type == "NM" &&
        isNaN(Number(observation.value))
    ) {
        failures.push(
            location + "Numeric OBX contains numeric value"
        );
    }

    if (!observation.units) {
        failures.push(location + "OBX units present");
    }

    if (!observation.reference_range) {
        failures.push(location + "OBX reference range present");
    }

    if (
        observation.abnormal_flag != "H" &&
        observation.abnormal_flag != "L" &&
        observation.abnormal_flag != "HH" &&
        observation.abnormal_flag != "LL" &&
        observation.abnormal_flag != "N"
    ) {
        failures.push(location + "OBX abnormal flag recognized");
    }

    if (
        observation.result_status != "F" &&
        observation.result_status != "P" &&
        observation.result_status != "C" &&
        observation.result_status != "I" &&
        observation.result_status != "X"
    ) {
        failures.push(location + "OBX result status recognized");
    }

    if (obrStatus != observation.result_status) {
        failures.push(
            location + "OBR and OBX result status agree"
        );
    }

    if (isSyntheticPanel) {
        if (!syntheticPanelMembers[observation.code]) {
            failures.push(
                location + "OBX belongs to SYN-CHEM-4 panel"
            );
        }
        if (observedPanelMembers[observation.code]) {
            failures.push(
                location + "Panel observation code is unique"
            );
        }
        observedPanelMembers[observation.code] = true;
    }
    else if (serviceCode != observation.code) {
        failures.push(
            location + "OBR and OBX observation codes agree"
        );
    }
}

if (isSyntheticPanel) {
    for (var requiredCode in syntheticPanelMembers) {
        if (!observedPanelMembers[requiredCode]) {
            failures.push(
                "SYN-CHEM-4 required member present: " +
                requiredCode
            );
        }
    }
}

var validationStatus =
    failures.length == 0
        ? "PASS"
        : "FAIL";

var failureReason =
    failures.join(" | ");

channelMap.put(
    "oru_validation_status",
    validationStatus
);

channelMap.put(
    "oru_validation_failure_category",
    failures.length == 0
        ? ""
        : "VALIDATION_ERROR"
);

channelMap.put(
    "oru_validation_failure_reason",
    failureReason
);

logger.info(
    "ORU validation: " +
    "status=" + validationStatus +
    ", control_id=" + messageControlId +
    ", failed_rule_count=" +
    failures.length +
    (
        failures.length > 0
            ? ", failed_rules=" + failureReason
            : ""
    )
);

properties.query:
/*
 * ORU_R01_IN
 * Successful ORU persistence
 *
 * Persist one ORU message record and one observation
 * record for the current simplified single-OBX profile.
 *
 * Future work will extend this to repeating OBX segments.
 */

var dbConn = null;

try {

    var dbUrl =
        java.lang.System.getenv(
            "INTEROP_DB_URL"
        );

    var dbUser =
        java.lang.System.getenv(
            "INTEROP_DB_USER"
        );

    var dbPassword =
        java.lang.System.getenv(
            "INTEROP_DB_PASSWORD"
        );

    if (
        dbUrl == null ||
        dbUser == null ||
        dbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }

    /*
     * Only persist messages that passed semantic validation.
     */
    var validationStatus =
        String(
            channelMap.get(
                "oru_validation_status"
            )
        );

    if (validationStatus != "PASS") {
        return;
    }

    var classifiedOutcome =
        String(
            channelMap.get(
                "audit_attempt_outcome"
            )
        );

    if (classifiedOutcome == "CONFLICTING_REUSE") {
        logger.warn(
            "ORU semantic persistence blocked for conflicting reuse: control_id=" +
            channelMap.get(
                "oru_message_control_id"
            )
        );
        return;
    }

    if (
        classifiedOutcome != "FIRST_DELIVERY" &&
        classifiedOutcome != "EXACT_REPLAY"
    ) {
        throw new Error(
            "Unrecognized ORU receipt classification: " +
            classifiedOutcome
        );
    }

    dbConn =
        DatabaseConnectionFactory
            .createDatabaseConnection(
                "org.postgresql.Driver",
                dbUrl,
                dbUser,
                dbPassword
            );

    dbConn.setAutoCommit(false);

    var logicalTransactionId =
        String(
            channelMap.get(
                "audit_logical_transaction_id"
            )
        );

    var recordedAuditId =
        String(
            channelMap.get(
                "audit_recorded_audit_id"
            )
        );

    /*
     * An exact replay normally reuses the existing canonical
     * semantic record. If the transport receipt survived a prior
     * partial failure but the semantic row did not, execution falls
     * through and repairs that missing row.
     */
    var existingMessageResult =
        dbConn.executeCachedQuery(
            "SELECT oru_message_id " +
            "FROM audit.oru_messages " +
            "WHERE transaction_id = CAST(? AS BIGINT)",
            [logicalTransactionId]
        );

    if (existingMessageResult.next()) {
        var existingOruMessageId =
            existingMessageResult.getLong(
                "oru_message_id"
            );

        channelMap.put(
            "oru_persisted_message_id",
            String(existingOruMessageId)
        );

        logger.info(
            "ORU exact replay reused canonical semantic record: " +
            "transaction_id=" + logicalTransactionId +
            ", oru_message_id=" + existingOruMessageId
        );

        dbConn.commit();

        return;
    }

    var insertMessageSql =
        "INSERT INTO audit.oru_messages (" +
        "message_control_id, " +
        "patient_identifier, " +
        "assigning_authority, " +
        "identifier_type, " +
        "placer_order_number, " +
        "filler_order_number, " +
        "sending_application, " +
        "sending_facility, " +
        "message_type, " +
        "trigger_event, " +
        "service_code, " +
        "service_text, " +
        "service_coding_system, " +
        "obr_result_status, " +
        "observation_at, " +
        "transaction_id, " +
        "source_audit_id, " +
        "provenance_status, " +
        "processing_status" +
        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, " +
        "CASE WHEN length(?) = 19 " +
        "THEN to_timestamp(?, 'YYYYMMDDHH24MISSTZHTZM') " +
        "ELSE to_timestamp(?, 'YYYYMMDDHH24MISS') END, " +
        "CAST(? AS BIGINT), CAST(? AS BIGINT), ?, ?) " +
        "RETURNING oru_message_id";

    var result =
        dbConn.executeCachedQuery(
            insertMessageSql,
            [
                String(
                    channelMap.get(
                        "oru_message_control_id"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_patient_identifier"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_assigning_authority"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_identifier_type"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_placer_order_number"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_filler_order_number"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_sending_application"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_sending_facility"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_message_type"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_trigger_event"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_service_code"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_service_text"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_service_coding_system"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_obr_status"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_observation_datetime"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_observation_datetime"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_observation_datetime"
                    )
                ),
                logicalTransactionId,
                recordedAuditId,
                "LINKED",
                "ACCEPTED"
            ]
        );

    if (!result.next()) {
        throw new Error(
            "ORU message insert did not return oru_message_id."
        );
    }

    var oruMessageId =
        result.getLong(
            "oru_message_id"
        );

    channelMap.put(
        "oru_persisted_message_id",
        String(oruMessageId)
    );

    var insertResultGroupSql =
        "INSERT INTO audit.oru_result_groups (" +
        "oru_message_id, result_group_sequence, obr_set_id, " +
        "placer_order_number, filler_order_number, " +
        "service_code, service_text, service_coding_system, " +
        "observation_at, result_status" +
        ") VALUES (?, 1, ?, ?, ?, ?, ?, ?, " +
        "CASE WHEN length(?) = 19 " +
        "THEN to_timestamp(?, 'YYYYMMDDHH24MISSTZHTZM') " +
        "ELSE to_timestamp(?, 'YYYYMMDDHH24MISS') END, ?) " +
        "RETURNING oru_result_group_id";

    var resultGroupResult =
        dbConn.executeCachedQuery(
            insertResultGroupSql,
            [
                oruMessageId,
                String(channelMap.get("oru_obr_set_id")),
                String(channelMap.get("oru_placer_order_number")),
                String(channelMap.get("oru_filler_order_number")),
                String(channelMap.get("oru_service_code")),
                String(channelMap.get("oru_service_text")),
                String(channelMap.get("oru_service_coding_system")),
                String(channelMap.get("oru_observation_datetime")),
                String(channelMap.get("oru_observation_datetime")),
                String(channelMap.get("oru_observation_datetime")),
                String(channelMap.get("oru_obr_status"))
            ]
        );

    if (!resultGroupResult.next()) {
        throw new Error(
            "ORU result-group insert did not return an identifier."
        );
    }

    var oruResultGroupId =
        resultGroupResult.getLong(
            "oru_result_group_id"
        );

    var persistedObservations = JSON.parse(
        String(channelMap.get("oru_observations_json"))
    );

    var insertObservationSql =
        "INSERT INTO audit.oru_observations (" +
        "oru_result_group_id, " +
        "oru_message_id, " +
        "observation_sequence, " +
        "obx_set_id, " +
        "observation_code, " +
        "observation_text, " +
        "observation_coding_system, " +
        "value_type, " +
        "observation_value, " +
        "units, " +
        "reference_range, " +
        "abnormal_flag, " +
        "result_status" +
        ") VALUES (?, ?, CAST(? AS INTEGER), ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

    for (var persistedIndex = 0;
         persistedIndex < persistedObservations.length;
         persistedIndex++) {
        var persistedObservation =
            persistedObservations[persistedIndex];

        dbConn.executeUpdate(
            insertObservationSql,
            [
                oruResultGroupId,
                oruMessageId,
                String(persistedObservation.sequence),
                String(persistedObservation.obx_set_id),
                String(persistedObservation.code),
                String(persistedObservation.text),
                String(persistedObservation.coding_system),
                String(persistedObservation.value_type),
                String(persistedObservation.value),
                String(persistedObservation.units),
                String(persistedObservation.reference_range),
                String(persistedObservation.abnormal_flag),
                String(persistedObservation.result_status)
            ]
        );
    }

    dbConn.commit();

    channelMap.put(
        "oru_persisted_observation_count",
        String(persistedObservations.length)
    );

    logger.info(
        "ORU persistence: " +
        "control_id=" +
        channelMap.get(
            "oru_message_control_id"
        ) +
        ", oru_message_id=" +
        oruMessageId +
        ", observation_count=" +
        persistedObservations.length
    );

}
catch (persistenceError) {
    if (dbConn != null) {
        try {
            dbConn.rollback();
        }
        catch (rollbackError) {
            logger.error(
                "ORU persistence rollback failed: " +
                rollbackError
            );
        }
    }

    throw persistenceError;
}
finally {

    if (dbConn != null) {
        dbConn.close();
    }
}

var dbConn = null;

try {

    var dbUrl =
        java.lang.System.getenv("INTEROP_DB_URL");

    var dbUser =
        java.lang.System.getenv("INTEROP_DB_USER");

    var dbPassword =
        java.lang.System.getenv("INTEROP_DB_PASSWORD");

    if (
        dbUrl == null ||
        dbUser == null ||
        dbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }

    dbConn =
        DatabaseConnectionFactory
            .createDatabaseConnection(
                "org.postgresql.Driver",
                dbUrl,
                dbUser,
                dbPassword
            );

    var rawPayload =
        String(
            connectorMessage.getRawData()
        );

    var digest =
        java.security.MessageDigest
            .getInstance("SHA-256");

    var hashBytes =
        digest.digest(
            new java.lang.String(
                rawPayload
            ).getBytes("UTF-8")
        );

    var payloadSha256 =
        java.lang.StringBuilder();

    for (
        var i = 0;
        i < hashBytes.length;
        i++
    ) {

        var hex =
            java.lang.Integer
                .toHexString(
                    (hashBytes[i] & 0xff) | 0x100
                )
                .substring(1);

        payloadSha256.append(hex);
    }

    var sql =
        "INSERT INTO audit.quarantined_messages (" +
        "message_control_id, " +
        "message_type, " +
        "trigger_event, " +
        "patient_identifier, " +
        "sending_application, " +
        "sending_facility, " +
        "failure_category, " +
        "failure_reason, " +
        "payload_text, " +
        "payload_sha256" +
        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

    var parameters =
        new java.util.ArrayList();

    parameters.add(
        channelMap.get(
            "oru_message_control_id"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_message_type"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_trigger_event"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_patient_identifier"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_sending_application"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_sending_facility"
        )
    );

    parameters.add(
        "VALIDATION_ERROR"
    );

    parameters.add(
        channelMap.get(
            "oru_validation_failure_reason"
        )
    );

    parameters.add(
        rawPayload
    );

    parameters.add(
        String(payloadSha256)
    );

    dbConn.executeUpdate(
        sql,
        parameters
    );

    logger.info(
        "ORU quarantine persistence: " +
        "control_id=" +
        channelMap.get(
            "oru_message_control_id"
        ) +
        ", status=QUARANTINED"
    );

}
catch (e) {

    logger.error(
        "ORU quarantine persistence failed: " +
        e
    );

    throw e;
}
finally {

    if (dbConn != null) {
        dbConn.close();
    }
}

channel.postprocessingScript:
/*
 * ORU_R01_IN postprocessor
 *
 * Translate ORU validation state into the
 * application-level HL7 acknowledgment.
 *
 * Policy:
 *
 * validation PASS -> AA
 * validation FAIL -> AR
 * processing error -> AE
 */

var validationStatus =
    channelMap.get("oru_validation_status");

var validationFailureReason =
    channelMap.get(
        "oru_validation_failure_reason"
    );

var classifiedOutcome =
    String(
        channelMap.get(
            "audit_attempt_outcome"
        )
    );

var connectorMessages =
    message.getConnectorMessages();

var destinationError = false;

var iterator =
    connectorMessages.entrySet().iterator();

while (iterator.hasNext()) {

    var entry = iterator.next();

    var metadataId =
        String(entry.getKey());

    if (metadataId != "0") {

        var status =
            String(
                entry.getValue().getStatus()
            );

        if (status == "ERROR") {
            destinationError = true;
            break;
        }
    }
}


/*
 * Read original source message.
 */

var sourceConnectorMessage =
    connectorMessages.get(0);

var rawMessage =
    String(
        sourceConnectorMessage.getRawData()
    );

var rawSegments =
    rawMessage.split(/\r\n|\n|\r/);

var mshSegment = null;

for (
    var i = 0;
    i < rawSegments.length;
    i++
) {

    if (
        rawSegments[i].indexOf("MSH|")
        == 0
    ) {
        mshSegment = rawSegments[i];
        break;
    }
}

var mshFields =
    mshSegment != null
        ? mshSegment.split("|")
        : [];


/*
 * Recover original sender/receiver context.
 */

var encodingCharacters =
    mshFields.length > 1
        ? mshFields[1]
        : "^~\\&";

var originalSendingApplication =
    mshFields.length > 2
        ? mshFields[2]
        : "LABSYSTEM";

var originalSendingFacility =
    mshFields.length > 3
        ? mshFields[3]
        : "INTEROPLAB";

var originalReceivingApplication =
    mshFields.length > 4
        ? mshFields[4]
        : "MIRTH";

var originalReceivingFacility =
    mshFields.length > 5
        ? mshFields[5]
        : "INTEROPLAB";

var originalControlId =
    mshFields.length > 9
        ? mshFields[9]
        : String(
            channelMap.get(
                "oru_message_control_id"
            )
        );

var processingId =
    mshFields.length > 10
        ? mshFields[10]
        : "P";

var versionId =
    mshFields.length > 11
        ? mshFields[11]
        : "2.5.1";


/*
 * Determine ACK policy.
 */

var ackCode;
var ackText;

if (destinationError) {

    ackCode = "AE";

    ackText =
        "Message processing error.";

}
else if (validationStatus == "FAIL") {

    ackCode = "AR";

    ackText =
        "Message rejected: " +
        (
            validationFailureReason
                ? String(
                    validationFailureReason
                )
                : "ORU validation failed."
        );

}
else if (classifiedOutcome == "CONFLICTING_REUSE") {

    ackCode = "AR";

    ackText =
        "Message rejected: conflicting reuse of message control ID.";

}
else if (validationStatus == "PASS") {

    ackCode = "AA";

    ackText =
        "Message accepted.";

}
else {

    ackCode = "AE";

    ackText =
        "Unable to determine ORU validation state.";
}


/*
 * Build ACK.
 */

var ackUuid =
    String(
        java.util.UUID.randomUUID()
    )
    .replace(/-/g, "")
    .substring(0, 16);

var ackControlId =
    "ACK" + ackUuid;

var timestamp =
    new java.text.SimpleDateFormat(
        "yyyyMMddHHmmss.SSS"
    ).format(
        new java.util.Date()
    );

var ack =
    "MSH|" +
    encodingCharacters +
    "|" +
    originalReceivingApplication +
    "|" +
    originalReceivingFacility +
    "|" +
    originalSendingApplication +
    "|" +
    originalSendingFacility +
    "|" +
    timestamp +
    "||" +
    "ACK^R01^ACK|" +
    ackControlId +
    "|" +
    processingId +
    "|" +
    versionId +
    "\r" +

    "MSA|" +
    ackCode +
    "|" +
    originalControlId +
    "|" +
    ackText +
    "\r";


logger.info(
    "ORU postprocessor ACK policy: " +
    "validation_status=" +
    validationStatus +
    ", destination_error=" +
    destinationError +
    ", attempt_outcome=" +
    classifiedOutcome +
    ", ack_code=" +
    ackCode +
    ", original_control_id=" +
    originalControlId
);

return ack;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
